package fi.palonkorpi.sideretro.ui

/**
 * Geometry for the Keytile drawings the legend renders (SPEC.md §5.1, SID-206).
 *
 * The artwork lives in the `sideretro/tiles-imgs` folder and is converted by `tools/tileart.py`. Every
 * shape a tile needs is a circle or a rounded rect, usually rotated about its own centre, so the
 * drawings become data rather than a rendering dependency — and artwork with a shape or an id the
 * app cannot use fails at conversion time instead of rendering wrong on the phone.
 *
 * Nothing here knows what a button *does*. Button ids are Android keycode names, so the renderer
 * asks `Keymap` what each one means under the running system, the inferred tile and the active
 * button mode. That is what keeps five drawings covering the spec's "five tiles × two orientations
 * × two button modes" — the labels are computed, not drawn.
 */
sealed interface Shape {
    val centreX: Float
    val centreY: Float

    /** Half the shape's smallest dimension. */
    val radius: Float

    /**
     * How far the shape reaches from its centre in a given direction.
     *
     * A label has to clear the button it belongs to, and [radius] is not that distance for anything
     * long: the Mini Controller's Start pill is 473 units on its long axis and 210 on its short one,
     * so placing a label at `radius` put the word "Start" straight on top of the pill.
     */
    fun extentTowards(dirX: Float, dirY: Float): Float

    data class Circle(override val centreX: Float, override val centreY: Float, val r: Float) : Shape {
        override val radius: Float get() = r
        override fun extentTowards(dirX: Float, dirY: Float): Float = r
    }

    data class RoundRect(
        override val centreX: Float,
        override val centreY: Float,
        val width: Float,
        val height: Float,
        val cornerX: Float,
        val cornerY: Float,
        val rotation: Float,
    ) : Shape {
        override val radius: Float get() = minOf(width, height) / 2f

        /** The support function of a box: turn the direction into the box's own frame, then project. */
        override fun extentTowards(dirX: Float, dirY: Float): Float {
            val a = Math.toRadians(-rotation.toDouble())
            val localX = dirX * kotlin.math.cos(a).toFloat() - dirY * kotlin.math.sin(a).toFloat()
            val localY = dirX * kotlin.math.sin(a).toFloat() + dirY * kotlin.math.cos(a).toFloat()
            return kotlin.math.abs(localX) * width / 2f + kotlin.math.abs(localY) * height / 2f
        }
    }
}

/** Whether a piece of the tile body is painted or merely outlined. */
enum class Role { SOLID, OUTLINE }

data class Piece(val shape: Shape, val role: Role)

/**
 * A glyph printed on the physical tile — the diamond's A/B/X/Y, a numpad's digits.
 *
 * [owner] is the button it sits on, so the renderer can drop it when that button has room to show
 * what it *does* instead. At the size the legend is drawn, one character per button is all that fits.
 */
data class Glyph(
    val text: String,
    val x: Float,
    val y: Float,
    val size: Float,
    val owner: String?,
)

/**
 * Hand-drawn SVG lettering retained as its original path commands.
 *
 * The Mini Controller's Start follows a diagonal pill and Select is manually broken into two
 * lines.  Rendering a guessed system-font word loses both of those choices, so source paths are
 * kept through conversion and painted at their authored coordinates.
 */
data class VectorGlyph(
    val pathData: String,
    val owner: String?,
    val translateX: Float = 0f,
    val translateY: Float = 0f,
    val rotation: Float = 0f,
)

/**
 * The portion of an SVG canvas occupied by the physical tile.
 *
 * Some Illustrator artboards deliberately leave generous breathing room around the drawing.  A
 * legend, however, is already given a precisely safe no-overlap rectangle; retaining that SVG
 * whitespace makes the physical reference look smaller than the space it is allowed to use.
 */
data class ArtBounds(
    val left: Float,
    val top: Float,
    val right: Float,
    val bottom: Float,
) {
    val width: Float get() = right - left
    val height: Float get() = bottom - top
    val centreX: Float get() = (left + right) / 2f
    val centreY: Float get() = (top + bottom) / 2f
}

data class TileArt(
    val width: Float,
    val height: Float,
    val body: List<Piece>,
    val legends: List<Glyph>,
    val vectors: List<VectorGlyph> = emptyList(),
    val buttons: Map<String, Shape>,
    /** Optional tight content frame. The source canvas remains the default for existing artwork. */
    val contentBounds: ArtBounds? = null,
)

private typealias Circle = Shape.Circle
private typealias RoundRect = Shape.RoundRect

